import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
// Bundle the existing, tested calculation functions for the server. No copied financial rules.
const files=['planning-data','product-data','growth-data','bill-data','money-data','budget-data','notification-data'];
const body=files.map(name=>readFileSync('js/'+name+'.js','utf8')).join('\n');
mkdirSync('supabase/functions/_shared',{recursive:true});
writeFileSync('supabase/functions/_shared/notification-engine.mjs',
    '// Generated by scripts/build-notifications.mjs. Public calculation code only.\n'+
    'export function buildNotifications(snapshot,today,now) {\n'+body+'\nreturn flowNotificationItems(snapshot,today,now);\n}\n'+
    'export '+readFileSync('js/notification-data.js','utf8').slice(readFileSync('js/notification-data.js','utf8').indexOf('function flowNotificationClock')));
